#include <vector>
#include <unordered_map>

class Solution {
public:
    int subarraysWithKDistinct(std::vector<int>& nums, int k) {
        auto atMost = [&](int m) {
            if (m == 0) return 0LL;
            std::unordered_map<int, int> count;
            int left = 0;
            long long ans = 0;
            for (int right = 0; right < (int)nums.size(); ++right) {
                if (count[nums[right]]++ == 0) m--;
                while (m < 0) {
                    if (--count[nums[left]] == 0) m++;
                    left++;
                }
                ans += (right - left + 1);
            }
            return ans;
        };
        return atMost(k) - atMost(k - 1);
    }
};

import java.util.*;

class Solution {
    public int subarraysWithKDistinct(int[] nums, int k) {
        return (int) (atMost(nums, k) - atMost(nums, k - 1));
    }

    private long atMost(int[] nums, int m) {
        if (m == 0) return 0;
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0;
        long ans = 0;
        for (int right = 0; right < nums.length; right++) {
            count.put(nums[right], count.getOrDefault(nums[right], 0) + 1);
            if (count.get(nums[right]) == 1) m--;
            while (m < 0) {
                count.put(nums[left], count.get(nums[left]) - 1);
                if (count.get(nums[left]) == 0) m++;
                left++;
            }
            ans += (right - left + 1);
        }
        return ans;
    }
}

function subarraysWithKDistinct(nums, k) {
    const atMost = (m) => {
        if (m === 0) return 0;
        const count = new Map();
        let left = 0;
        let ans = 0;
        for (let right = 0; right < nums.length; right++) {
            const x = nums[right];
            count.set(x, (count.get(x) || 0) + 1);
            if (count.get(x) === 1) m--;
            while (m < 0) {
                const lVal = nums[left];
                count.set(lVal, count.get(lVal) - 1);
                if (count.get(lVal) === 0) m++;
                left++;
            }
            ans += (right - left + 1);
        }
        return ans;
    };
    return atMost(k) - atMost(k - 1);
